<script lang="ts">
	import { onMount } from "svelte";
	import { dpoPairLoss, encodeToyBpe, maskedNll, trainingBudget, trainToyBpe } from "@/utils/model-pipeline";
	let english = $state(false);
	let active = $state(0);
	let size = $state(0.15);
	let context = $state(128);
	let microbatch = $state(1);
	let accumulation = $state(1);
	let steps = $state(8);
	let grouped = $state(true);
	let mergeCount = $state(2);
	let tokenizerInput = $state("lower");
	let targetProbability = $state(0.4);
	let assistantOnly = $state(true);
	let policyGap = $state(0);
	let beta = $state(0.1);
	let tokenWeighted = $state(true);
	let exportParts = $state([true, true, false, false]);
	let throughput = $state<number | undefined>(undefined);
	const trainingWords = ["low", "low", "lower", "lowest"];
	const toyTokenizer = $derived(trainToyBpe(trainingWords, mergeCount));
	const encodedWords = $derived(encodeToyBpe(tokenizerInput, toyTokenizer));
	const pretrainProbabilities = $derived([0.25, targetProbability, 0.8, 0.01]);
	const pretrainLoss = $derived(maskedNll(pretrainProbabilities, [true, true, true, false]));
	const sftProbabilities = [0.05, 0.1, 0.1, 0.5, 0.4, 0.8, 0.01];
	const sftMask = $derived([!assistantOnly, !assistantOnly, !assistantOnly, true, true, true, false]);
	const sftLoss = $derived(maskedNll(sftProbabilities, sftMask));
	const dpoLoss = $derived(dpoPairLoss(policyGap, 0, beta));
	const fixedEvaluation = [
		{ label: "A", short: [0.8, 0.8], long: Array<number>(8).fill(0.2) },
		{ label: "B", short: [0.5, 0.5], long: Array<number>(8).fill(0.3) },
	];
	function meanNll(values: number[]) { return maskedNll(values, values.map(() => true)).mean ?? 0; }
	function evaluationScore(row: typeof fixedEvaluation[number]) {
		return tokenWeighted ? meanNll([...row.short, ...row.long]) : (meanNll(row.short) + meanNll(row.long)) / 2;
	}
	let copyStatus = $state<"" | "ok" | "error">("");
	const stages = [
		{ id: "data", short: "数据", shortEn: "Data", title: "先决定，模型将读到什么。", titleEn: "First, decide what the model will read.", description: "记录语料来源和使用许可，清理空文本与异常样本，去重后按文档组划分数据。训练集用于更新参数，验证集用于选择配置，最终测试集留到比较方案时。", descriptionEn: "Record sources and licenses, clean empty or malformed examples, deduplicate, and split by document group. Training data updates parameters, validation data guides configuration, and the final test set is reserved for comparison.", input: "原始文档 + 来源与许可清单", inputEn: "Raw documents + source and license manifest", output: "train / validation / test + 数据版本", outputEn: "train / validation / test + data version", check: "同一文档、近重复文本和同源片段不能跨集合；后训练数据也要检查与评测集的重叠。", checkEn: "Keep documents, near-duplicates, and related chunks in one split. Also check post-training data for overlap with evaluation sets.", artifact: "manifest.json · train.jsonl · validation.jsonl · test.jsonl", action: "调整下方的切分方式，看看重复文档去了哪里。", actionEn: "Change the splitting rule below and see where the duplicate document goes." },
		{ id: "tokenizer", short: "分词", shortEn: "Tokenizer", title: "把文字，变成固定的接口。", titleEn: "Turn text into a stable interface.", description: "只用训练语料拟合分词器，记录词表、特殊 token 和版本。把文档编码、追加结束标记，再按上下文长度打包；padding 部分不计入训练损失。", descriptionEn: "Fit the tokenizer on training text only and version its vocabulary and special tokens. Encode documents, add end markers, and pack sequences to the chosen context length. Mask padding out of the training loss.", input: "训练语料 + 分词配置", inputEn: "Training corpus + tokenizer configuration", output: "固定分词器 + token 数据块", outputEn: "Frozen tokenizer + token blocks", check: "检查编码/解码、特殊 token 与词表大小；验证集只能编码，不能参与拟合分词器。", checkEn: "Check encode/decode behavior, special tokens, and vocabulary size. Validation text is encoded but never used to fit the tokenizer.", artifact: "tokenizer.json · tokenizer.meta.json", action: "上下文长度影响每个训练序列能看到的范围，也影响显存与内存需求。", actionEn: "Context length controls how much each sequence can see and affects activation memory." },
		{ id: "pretrain", short: "预训练", shortEn: "Pretrain", title: "从随机权重，开始预测下一个 token。", titleEn: "Predict the next token, starting from random weights.", description: "初始化一个小型 decoder-only Transformer，以自回归目标做完整参数训练。先打通少量更新、保存、恢复和固定集评估，再增加 token 预算。", descriptionEn: "Initialize a small decoder-only Transformer and train all its parameters with an autoregressive objective. First connect a few updates, saving, resuming, and fixed-set evaluation, then increase the token budget.", input: "随机初始化模型 + 训练 token", inputEn: "Randomly initialized model + training tokens", output: "基座 checkpoint + 优化器状态 + 运行日志", outputEn: "Base checkpoint + optimizer state + run log", check: "固定随机种子和验证集；检查 loss 是否有限、梯度是否有效、断点恢复后数据位置是否一致。", checkEn: "Fix the seed and validation set. Check finite loss, useful gradients, and consistent data position when resuming.", artifact: "pretrain/checkpoint.pt · pretrain/report.json", action: "先用 tiny 做少量步 smoke test，再把约 30M 作为首个完整实验。100M 与 500M 都需要吞吐、峰值内存和磁盘测量后再决定。", actionEn: "First run a tiny smoke test, then use approximately 30M for the first full experiment. Both 100M and 500M require throughput, peak-memory, and disk measurements." },
		{ id: "sft", short: "指令微调", shortEn: "SFT", title: "让续写，变成对指令的回应。", titleEn: "Turn continuation into an instruction response.", description: "接续自己的预训练 checkpoint，统一对话模板，用指令与回答样本训练。只在需要学习的 assistant 回答部分计算损失，保持验证提示词和生成参数固定。", descriptionEn: "Continue from your own pretrained checkpoint with a consistent chat template and instruction-response examples. Compute loss on the intended assistant responses, and keep validation prompts and generation settings fixed.", input: "自己的基座 checkpoint + 指令数据", inputEn: "Your base checkpoint + instruction data", output: "SFT checkpoint + 对话模板", outputEn: "SFT checkpoint + chat template", check: "核对标签掩码、角色边界与结束符；用相同提示词比较基座与 SFT 输出。", checkEn: "Check label masking, role boundaries, and stop tokens. Compare base and SFT outputs on the same prompts.", artifact: "sft/checkpoint.pt · sft/report.json", action: "小模型先学习清晰的输出格式和窄任务，目标与能力范围保持一致。", actionEn: "Use small models to learn clear formats and narrow tasks, with goals matched to their capacity." },
		{ id: "dpo", short: "偏好优化", shortEn: "DPO", title: "让偏好，成为可以比较的训练信号。", titleEn: "Turn preferences into a comparable training signal.", description: "为相同 prompt 准备 chosen / rejected 成对回答，以 SFT checkpoint 作为起点和固定参考。DPO 直接优化相对偏好，记录 β、数据构造方式与训练范围。", descriptionEn: "Prepare chosen/rejected responses to the same prompt, using the SFT checkpoint as both the starting policy and a frozen reference. DPO optimizes relative preferences; record beta, data construction, and which parameters are trained.", input: "SFT checkpoint + 偏好对 + 固定参考", inputEn: "SFT checkpoint + preference pairs + frozen reference", output: "DPO checkpoint + 偏好训练日志", outputEn: "DPO checkpoint + preference training log", check: "用独立偏好集比较 SFT 与 DPO，并检查格式、长度和基础能力变化。固定参考模型还会占用额外内存。", checkEn: "Compare SFT and DPO on held-out preferences, and check format, length, and base capabilities. The frozen reference model needs additional memory.", artifact: "dpo/checkpoint.pt · dpo/report.json", action: "一次偏好分数提高，需要和其他指标一起判断；它本身不能代表通用能力提高。", actionEn: "Judge preference improvements together with other metrics; preference scores alone do not establish a general capability gain." },
		{ id: "evaluate", short: "评测", shortEn: "Evaluate", title: "用同一把尺子，比较每次改变。", titleEn: "Compare each change with the same ruler.", description: "保留随机初始化、预训练、SFT 与 DPO 四个快照。在固定文本上计算 token 加权 NLL 与 perplexity，在固定任务上比较格式、正确率和偏好，同时保留原始输出。", descriptionEn: "Keep random, pretrained, SFT, and DPO snapshots. Measure token-weighted NLL and perplexity on fixed text; compare format, accuracy, and preference on fixed tasks, keeping raw outputs.", input: "各阶段 checkpoint + 冻结评测集", inputEn: "Stage checkpoints + frozen evaluation sets", output: "可追溯的指标表 + 原始生成结果", outputEn: "Traceable metrics + raw generations", check: "只在相同分词器、语料与掩码下比较 perplexity；任务分数注明样本数和判分规则。", checkEn: "Compare perplexity only with the same tokenizer, corpus, and masking. Report sample counts and scoring rules for task metrics.", artifact: "evaluation.json · summary.json", action: "这里呈现流程和预算；训练曲线与能力结果将由实际运行日志生成。", actionEn: "This workbench shows the workflow and budget; learning curves and capability results will come from actual run logs." },
		{ id: "deploy", short: "部署", shortEn: "Deploy", title: "把一次训练，交付成可重现的模型。", titleEn: "Deliver a reproducible model from a training run.", description: "一起导出权重、配置、分词器、对话模板和模型说明。先验证本地加载和生成，再把量化作为独立比较，记录模型大小、质量变化与推理速度。", descriptionEn: "Export weights, configuration, tokenizer, chat template, and a model card together. Confirm local loading and generation first, then compare quantization separately, recording size, quality changes, and inference speed.", input: "选定 checkpoint + 配套配置", inputEn: "Selected checkpoint + matching configuration", output: "本地推理入口 + 模型说明 + 复现命令", outputEn: "Local inference entry + model card + reproduction commands", check: "同一提示词比较导出前后的生成；量化后重新评测，记录运行环境与生成参数。", checkEn: "Compare generations before and after export on the same prompts. Re-evaluate quantized models and record the environment and decoding settings.", artifact: "checkpoint.pt · generate --chat · summary.json", action: "当前骨架直接加载 checkpoint 内嵌的权重、配置和分词器做本地 CLI 推理。格式转换与量化留待独立验证；失败样例回到下一轮数据和评测。", actionEn: "The current skeleton loads weights, configuration, and tokenizer embedded in the checkpoint for local CLI inference. Format conversion and quantization need separate validation; failure cases inform the next data and evaluation cycle." },
	];
	const documents = [
		{ id: "A · 1", group: "A", text: "风吹过山谷。", textEn: "Wind passes through the valley.", split: "train", naive: "train" },
		{ id: "A · 2", group: "A", text: "风吹过山谷。", textEn: "Wind passes through the valley.", split: "duplicate", naive: "validation" },
		{ id: "B", group: "B", text: "河水流向大海。", textEn: "The river flows toward the sea.", split: "train", naive: "train" },
		{ id: "C", group: "C", text: "种子在春天发芽。", textEn: "Seeds sprout in spring.", split: "validation", naive: "validation" },
		{ id: "D", group: "D", text: "月光照亮了窗台。", textEn: "Moonlight lights up the windowsill.", split: "test", naive: "test" },
	];
	const current = $derived(stages[active]);
	const budget = $derived(trainingBudget(size * 1_000_000, context, microbatch, accumulation, steps));
	const memory = $derived(budget.stateGiB);
	const tokensPerStep = $derived(budget.tokensPerUpdate);
	const tokens = $derived(budget.tokens);
	const tokenDisplayDivisor = $derived(tokens >= 1_000_000 ? 1_000_000 : tokens >= 1_000 ? 1_000 : 1);
	const runHours = $derived(throughput && Number.isFinite(throughput) && throughput > 0 ? tokens / throughput / 3600 : null);
	const tokensPerParameter = $derived(tokens / (size * 1_000_000));
	function t(zh: string, en: string) { return english ? en : zh; }
	function number(value: number) { return value.toLocaleString(english ? "en-US" : "zh-CN"); }
	function choose(index: number) { active = Math.max(0, Math.min(stages.length - 1, index)); copyStatus = ""; }
	function settings() { return { stage: current.id, size: String(size), context: String(context), microbatch: String(microbatch), accumulation: String(accumulation), steps: String(steps) }; }
	async function share() {
		const url = new URL(location.href); url.search = new URLSearchParams(settings()).toString(); history.replaceState({}, "", url);
		try { await navigator.clipboard.writeText(url.href); copyStatus = "ok"; } catch { copyStatus = "error"; }
	}
	onMount(() => {
		const sync = () => { english = document.documentElement.lang.startsWith("en"); };
		sync(); document.addEventListener("site-locale-change", sync);
		const params = new URL(location.href).searchParams;
		const queryStage = stages.findIndex((stage) => stage.id === params.get("stage")); if (queryStage >= 0) active = queryStage;
		const read = (key: string, options: number[], fallback: number) => { const value = Number(params.get(key)); return options.includes(value) ? value : fallback; };
		size = read("size", [0.15, 30, 100, 500], 0.15); context = read("context", [128, 256, 512, 1024], 128); microbatch = read("microbatch", [1, 2, 4], 1); accumulation = read("accumulation", [1, 8, 16, 32], 1); steps = read("steps", [8, 100, 1000, 5000, 25000], 8);
		return () => document.removeEventListener("site-locale-change", sync);
	});
</script>

<section class="pipeline" aria-label={t("小模型全链路互动工作台", "Small-model pipeline workbench")}>
	<div class="workbench-heading"><span>MODEL WORKBENCH</span><span class="planning-dot">{t("教学示例 · 无训练结果", "TEACHING EXAMPLES · NO TRAINING RESULTS")}</span></div>
	<nav class="stage-nav" aria-label={t("训练阶段", "Training stages")}>
		{#each stages as stage, index}<button class:active={active === index} aria-current={active === index ? "step" : undefined} onclick={() => choose(index)}><span>0{index + 1}</span><strong>{t(stage.short, stage.shortEn)}</strong><i aria-hidden="true">{index === 6 ? "↺" : "→"}</i></button>{/each}
	</nav>
	<div class="stage-panel">
		<div class="stage-copy" aria-live="polite" aria-atomic="true"><span class="step-code">0{active + 1} / 07 — {current.id.toUpperCase()}</span><h2>{t(current.title, current.titleEn)}</h2><p>{t(current.description, current.descriptionEn)}</p><div class="artifact-flow"><div><small>INPUT</small><strong>{t(current.input, current.inputEn)}</strong></div><span aria-hidden="true">↓</span><div class="output"><small>OUTPUT</small><strong>{t(current.output, current.outputEn)}</strong></div></div></div>
		<aside class="stage-insight"><div class="model-schematic" aria-hidden="true"><div class="schematic-orbit"></div><span class="schematic-chip">{active < 2 ? "DATA" : active === 2 ? "θ₀ → θ" : active === 3 ? "SFT" : active === 4 ? "DPO" : active === 5 ? "EVAL" : "MODEL"}</span><span class="schematic-a">{active < 2 ? "DOCUMENT" : "INPUT"}</span><span class="schematic-b">{active < 2 ? "TOKENS" : "OUTPUT"}</span><i class="schematic-node one"></i><i class="schematic-node two"></i><i class="schematic-node three"></i></div><h3>{t("这一阶段，检查什么？", "What should we check?")}</h3><p>{t(current.check, current.checkEn)}</p><span class="artifact-label">{t("项目产物 · 按当前骨架命名", "PROJECT ARTIFACTS · CURRENT SKELETON")}</span><code>{current.artifact}</code></aside>
	</div>
	<div class="stage-bottom"><p>{t(current.action, current.actionEn)}</p><div><button class="plain" onclick={() => choose(active - 1)} disabled={active === 0}>← {t("上一步", "Previous")}</button><button onclick={() => choose(active === 6 ? 0 : active + 1)}>{active === 6 ? t("回到数据", "Back to data") : t("下一步", "Next")} {active === 6 ? "↺" : "→"}</button></div></div>
	{#if active === 0}
		<section class="split-demo"><div class="subheading"><div><span class="step-code">TRY A SMALL EXAMPLE</span><h3>{t("五条文本，怎么分才合适？", "Five texts. How should we split them?")}</h3></div><label class="switch"><input type="checkbox" bind:checked={grouped} /><span>{t("先去重，再按文档组划分", "Deduplicate, then split by document group")}</span></label></div><div class="sample-list">{#each documents as document}{@const split = grouped ? document.split : document.naive}<div class:duplicate={split === "duplicate"} class:leaked={!grouped && document.group === "A"}><span class="document-id">{document.id}</span><span>{t(document.text, document.textEn)}</span><code>{split === "duplicate" ? t("去重移除", "removed") : split}</code></div>{/each}</div><p class:leak-warning={!grouped} class="split-feedback" role="status">{grouped ? t("相同的 A 文档保留一条，验证和测试使用其他文档。这里展示确定的分组示例。", "Keep one copy of document A, and use other documents for validation and testing. This is a fixed grouping example.") : t("A 的相同内容同时出现在 train 与 validation：验证分数会受到训练内容泄漏的影响。", "Identical content from A appears in both train and validation: the validation score is affected by training-data leakage.")}</p><p class="fine-print">{t("实际语料还需要近重复检测、来源分组和评测集排重；这个小例子只演示精确重复。", "Real corpora also need near-duplicate detection, source grouping, and evaluation-set decontamination. This small example only demonstrates exact duplicates.")}</p></section>
	{:else if active === 1}
		<section class="split-demo" aria-labelledby="tokenizer-heading">
			<div class="subheading"><div><span class="step-code">01 / FIT → FREEZE → ENCODE</span><h3 id="tokenizer-heading">{t("亲手合并一次分词规则。", "Build a tokenizer, one merge at a time.")}</h3></div><span class="example-badge">{t("实际执行的简化 BPE", "EXECUTABLE TOY BPE")}</span></div>
			<p class="demo-intro">{t("训练语料固定为 low × 2、lower、lowest。每次合并最常见的相邻符号；次数相同则取最早出现的组合。输入的新词只编码，不参与拟合。", "Training text is fixed: low × 2, lower, lowest. Each step merges the most frequent adjacent pair; ties use first occurrence. The new word is encoded without fitting on it.")}</p>
			<div class="demo-controls"><label>{t("合并次数", "Merge steps")}<input type="range" min="0" max="6" step="1" bind:value={mergeCount} /><output>{mergeCount}</output></label><label>{t("待编码文本（最多 32 字符）", "Text to encode (up to 32 characters)")}<input type="text" maxlength="32" bind:value={tokenizerInput} spellcheck="false" autocomplete="off" /></label></div>
			<div class="toy-grid"><div><h4>{t("训练得到的规则", "Learned rules")}</h4><ol class="merge-list">{#each toyTokenizer.merges as merge}<li><code>{merge.left} + {merge.right} → {merge.left + merge.right}</code><span>× {merge.count}</span></li>{/each}</ol>{#if !mergeCount}<p class="fine-print">{t("还没有合并，只有初始字符表。", "No merges yet: only the initial alphabet.")}</p>{/if}</div><div><h4>{t("冻结词表后的编码", "Encoding with the frozen vocabulary")}</h4><div class="token-strip" aria-live="polite">{#each encodedWords as word}<span class="token-word">{#each word as token}<span class:unknown={token === "<unk>"} class="token"><code>{token}</code><small>ID {toyTokenizer.vocabulary.indexOf(token)}</small></span>{/each}</span>{/each}</div><p class="fine-print">{t("试试 snow：n 未出现在训练字符表，会变成 <unk>。", "Try snow: n is absent from the training alphabet and becomes <unk>.")}</p></div></div>
			<p class="fine-print">{t("这是词内字符 BPE：空白只用于分词，未保留原始空白，不能当作可逆的生产分词器。训练项目使用字节级 BPE；它在训练集上单独拟合，包含 256 个基础字节，并验证编解码和特殊 token。", "This is character BPE within words: whitespace separates words and is not preserved, so this is not a reversible production tokenizer. The project fits byte-level BPE separately on its training split, includes all 256 base bytes, and checks round-trips and special tokens.")}</p>
		</section>
	{:else if active === 2 || active === 3}
		<section class="split-demo" aria-labelledby="loss-heading">
			<div class="subheading"><div><span class="step-code">02 / TARGETS & LOSS</span><h3 id="loss-heading">{active === 2 ? t("预测下一个 token，损失从哪里来？", "Where does next-token loss come from?") : t("同一段对话，哪些 token 要学？", "Which tokens should the model learn from?")}</h3></div><span class="example-badge">{t("给定概率的教学计算", "CALCULATION WITH GIVEN PROBABILITIES")}</span></div>
			{#if active === 2}
				<p class="demo-intro">{t("输入 [BOS, 风, 动, EOS]，向右错开后的目标是 [风, 动, EOS, PAD]。改变模型对正确目标「动」分配的概率，观察平均负对数似然。这里没有运行神经网络或更新权重。", "For input [BOS, wind, moves, EOS], shifted targets are [wind, moves, EOS, PAD]. Change the probability assigned to the correct target “moves” and inspect mean negative log-likelihood. No neural network or weight update is run here.")}</p>
				<label class="range-control">{t("P(动 | BOS, 风)", "P(moves | BOS, wind)")}<input type="range" min="0.05" max="0.95" step="0.05" bind:value={targetProbability} /><output>{targetProbability.toFixed(2)}</output></label>
				<div class="token-strip">{#each [t("风", "wind"), t("动", "moves"), "EOS", "PAD"] as token, index}<span class:masked={index === 3} class="token"><code>{token}</code><small>p = {pretrainProbabilities[index].toFixed(2)}</small><small>{index === 3 ? t("不计损失", "masked") : `−ln(p) = ${(-Math.log(pretrainProbabilities[index])).toFixed(3)}`}</small></span>{/each}</div>
				<p class="calculation" role="status">NLL = {pretrainLoss.total.toFixed(3)} / {pretrainLoss.count} = {pretrainLoss.mean?.toFixed(3)} {t("nats / 目标 token", "nats / target token")}</p>
			{:else}
				<p class="demo-intro">{t("下方是已错位对齐的目标 token。提示词仍作为上下文被模型读取；mask 只决定哪些位置计入损失。回答结束符 EOS 计入，PAD 始终排除。每个位置的概率是人为给定值。", "These are shifted target tokens. The prompt remains visible as context; the mask only selects positions for loss. The response EOS is included and PAD is always excluded. Probabilities are hand-set teaching values.")}</p>
				<label class="switch mask-switch"><input type="checkbox" bind:checked={assistantOnly} /><span>{t("只训练 assistant 回答", "Train on assistant responses only")}</span></label>
				<div class="token-strip">{#each ["USER", t("回答", "answer"), "ASSISTANT", t("风", "wind"), t("动", "moves"), "EOS", "PAD"] as token, index}<span class:masked={!sftMask[index]} class="token"><code>{token}</code><small>{index < 3 ? t("提示区域", "prompt") : index === 6 ? "padding" : t("回答区域", "response")}</small><small>mask = {sftMask[index] ? 1 : 0}</small><small>p = {sftProbabilities[index].toFixed(2)}</small></span>{/each}</div>
				<p class="calculation" role="status">NLL = {sftLoss.total.toFixed(3)} / {sftLoss.count} = {sftLoss.mean?.toFixed(3)} {t("nats / 目标 token", "nats / target token")}</p>
			{/if}
			<p class="fine-print">{t("NLL = −Σ maskᵢ · ln p(targetᵢ | 前文) / Σ maskᵢ。不同 mask 定义了不同目标，数值变小不能单独证明模型更好。", "NLL = −Σ maskᵢ · ln p(targetᵢ | prefix) / Σ maskᵢ. Different masks define different objectives; a smaller number alone does not establish a better model.")}</p>
		</section>
	{:else if active === 4}
		<section class="split-demo" aria-labelledby="dpo-heading">
			<div class="subheading"><div><span class="step-code">03 / A RELATIVE PREFERENCE</span><h3 id="dpo-heading">{t("相对参考模型，偏好改变了多少？", "How has preference changed relative to the reference?")}</h3></div><span class="example-badge">{t("单个偏好对 · 公式示意", "ONE PAIR · FORMULA DEMO")}</span></div>
			<p class="demo-intro">{t("同一个 prompt 下，把 chosen 和 rejected 的回答序列对数概率作差，得到 Δ。此例固定 Δref = 0，只调整策略差值与 β。序列概率只累加回答 token，不含 prompt。", "For one prompt, subtract the rejected response's sequence log-probability from the chosen response's to get Δ. Here Δref = 0 stays fixed while policy Δ and beta vary. Sequence log-probabilities sum response tokens only, excluding the prompt.")}</p>
			<div class="demo-controls"><label>Δpolicy = log π(chosen) − log π(rejected)<input type="range" min="-4" max="4" step="0.25" bind:value={policyGap} /><output>{policyGap.toFixed(2)}</output></label><label>β<input type="range" min="0.1" max="1" step="0.1" bind:value={beta} /><output>{beta.toFixed(1)}</output></label></div>
			<div class="dpo-track"><span>{t("更偏向 rejected", "Toward rejected")}</span><meter min="-4" max="4" value={policyGap} aria-label={t("策略对数概率差", "Policy log-probability gap")}></meter><span>{t("更偏向 chosen", "Toward chosen")}</span></div>
			<p class="calculation" role="status">L = −log σ(β · [Δpolicy − Δref]) = {dpoLoss.toFixed(4)}</p>
			<p class="fine-print">{t("策略等于参考时 L = ln 2 ≈ 0.6931。提高相对 chosen 概率会降低这个偏好对的损失；不代表整体任务能力提升。此处不生成回答、不训练奖励模型，也不运行 DPO 更新。", "At the reference, L = ln 2 ≈ 0.6931. Increasing relative chosen probability reduces this pair's loss; it does not demonstrate broader task gains. This demo generates no responses, trains no reward model, and performs no DPO updates.")}</p>
		</section>
	{:else if active === 5}
		<section class="split-demo" aria-labelledby="evaluation-heading">
			<div class="subheading"><div><span class="step-code">04 / A FIXED EVALUATION</span><h3 id="evaluation-heading">{t("平均方式，也能改变排名。", "Averaging can change the ranking.")}</h3></div><label class="switch"><input type="checkbox" bind:checked={tokenWeighted} /><span>{t("按目标 token 数加权", "Weight by target-token count")}</span></label></div>
			<p class="demo-intro">{t("固定两篇文本：短文 2 个目标 token，长文 8 个。A、B 是两组人为指定的概率，不是真实 checkpoint。分词器、文本和 mask 均不变，只切换聚合方式。", "Fix two documents: 2 target tokens in the short one, 8 in the long one. A and B are hand-set probabilities, not real checkpoints. Tokenizer, text, and masks stay unchanged; only aggregation changes.")}</p>
			<div class="table-scroll"><table><caption>{t("教学对照 · 数值由给定概率计算", "Teaching comparison · computed from given probabilities")}</caption><thead><tr><th scope="col">{t("示例", "Example")}</th><th scope="col">{t("短文 p", "Short p")}</th><th scope="col">{t("长文 p", "Long p")}</th><th scope="col">{tokenWeighted ? "Token NLL" : t("篇均 NLL", "Doc mean NLL")}</th><th scope="col">{tokenWeighted ? "Perplexity" : "exp(doc mean)"}</th></tr></thead><tbody>{#each fixedEvaluation as row}<tr><th scope="row">{row.label}</th><td>{row.short[0].toFixed(1)} × 2</td><td>{row.long[0].toFixed(1)} × 8</td><td>{evaluationScore(row).toFixed(3)}</td><td>{Math.exp(evaluationScore(row)).toFixed(3)}</td></tr>{/each}</tbody></table></div>
			<p class="split-feedback" role="status">{tokenWeighted ? t("按 token 汇总，B 的 NLL 更低。先累加所有目标 token 的损失，再除以 10。", "With token weighting, B has lower NLL. Sum losses across all target tokens, then divide by 10.") : t("按篇平均后，A 看起来更好：短文和长文被给了相同权重。这不是整个语料的 token perplexity。", "With document averaging, A appears better: short and long documents receive equal weight. This is not token perplexity over the corpus.")}</p>
			<p class="fine-print">{t("真实评测应冻结数据与判分规则，保存样本数、原始输出和版本。NLL、任务准确率、格式遵循和偏好分别报告；测试集不用于调参。", "Real evaluation freezes data and scoring, saving sample counts, raw outputs, and versions. Report NLL, task accuracy, format compliance, and preferences separately; do not tune on the test set.")}</p>
		</section>
	{:else if active === 6}
		<section class="split-demo" aria-labelledby="export-heading">
			<div class="subheading"><div><span class="step-code">05 / EXPORT CONTRACT</span><h3 id="export-heading">{t("只有权重，能交付吗？", "Are weights alone enough to ship?")}</h3></div><span class="example-badge">{t("产物清单练习", "ARTIFACT CHECKLIST EXERCISE")}</span></div>
			<p class="demo-intro">{t("勾选一个可复现模型包应包含的内容。此清单是练习，不会检查或生成实际文件；全部勾选后仍需在干净环境中验证。", "Select the contents of a reproducible model package. This exercise does not inspect or generate real files; selecting everything still requires validation in a clean environment.")}</p>
			<div class="export-checklist">{#each [t("权重及校验值", "Weights and checksums"), t("架构配置与版本", "Architecture configuration and version"), t("分词器、特殊 token 与对话模板", "Tokenizer, special tokens, and chat template"), t("模型说明、环境、推理命令与固定评测记录", "Model card, environment, inference command, and fixed evaluation records")] as part, index}<label><input type="checkbox" bind:checked={exportParts[index]} />{part}</label>{/each}</div>
			<p class="split-feedback" role="status">{exportParts.every(Boolean) ? t("清单齐全。下一步：从导出目录独立加载，用固定输入核对 token ID 与生成输出。", "Checklist complete. Next: load the export independently and compare token IDs and generations on fixed inputs.") : t("缺少接口或复现材料：相同权重可能被不同分词器或模板解释成不同的输入。", "Interface or reproduction artifacts are missing: a different tokenizer or template can feed different inputs to the same weights.")}</p>
			<p class="fine-print">{t("量化是独立的质量与速度对照，需要导出兼容性验证。4-bit 权重的理论位数不等于磁盘包大小或推理峰值内存；还需分组尺度、KV cache、临时张量和框架。", "Quantization is a separate quality/speed comparison and requires export compatibility checks. Theoretical 4-bit weight storage is not package size or peak inference memory; scales, KV cache, temporary tensors, and runtime also count.")}</p>
		</section>
	{/if}
	<section class="budget-section"><div class="subheading"><div><span class="step-code">PLAN THE FIRST RUN</span><h3>{t("先算预算，再扩大规模。", "Size the run before scaling it.")}</h3></div><span class="device-label">M4 AIR · 8 GPU · 16 GiB</span></div><div class="budget-controls"><label>{t("规划参数量", "Planned parameters")}<select bind:value={size}><option value={0.15}>{t("约 0.15M · tiny 冒烟估算", "~0.15M · tiny smoke estimate")}</option><option value={30}>{t("约 30M · 首个完整实验", "~30M · first full experiment")}</option><option value={100}>{t("约 100M · 待实测", "~100M · profile first")}</option><option value={500}>{t("约 500M · 待实测", "~500M · profile first")}</option></select></label><label>{t("上下文长度", "Context length")}<select bind:value={context}>{#each [128,256,512,1024] as value}<option value={value}>{value}</option>{/each}</select></label><label>{t("微批量 · 序列数", "Microbatch · sequences")}<select bind:value={microbatch}>{#each [1,2,4] as value}<option value={value}>{value}</option>{/each}</select></label><label>{t("梯度累积次数", "Gradient accumulation")}<select bind:value={accumulation}>{#each [1,8,16,32] as value}<option value={value}>{value}</option>{/each}</select></label><label>{t("优化器更新步数", "Optimizer updates")}<select bind:value={steps}>{#each [8,100,1000,5000,25000] as value}<option value={value}>{number(value)}</option>{/each}</select></label></div>
		<div class="budget-results" aria-live="polite"><div class="memory-result"><small>{t("FP32 ADAM 参数状态估算下界", "FP32 ADAM PARAMETER-STATE LOWER BOUND")}</small><strong>{memory.toFixed(size < 1 ? 4 : 2)} <span>GiB</span></strong><div class="memory-track" aria-hidden="true"><i style={`width:${Math.min(memory / 16 * 100, 100)}%`}></i></div><p>{t("对照 16 GiB 统一内存", "Relative to 16 GiB unified memory")}</p></div><div><small>{t("规划训练 TOKEN 数", "PLANNED TRAINING TOKENS")}</small><strong>{(tokens / tokenDisplayDivisor).toLocaleString(english ? "en-US" : "zh-CN", { maximumFractionDigits: 2 })} <span>{tokens >= 1_000_000 ? "M" : tokens >= 1_000 ? "K" : "tokens"}</span></strong><p>{number(tokensPerStep)} tokens / {t("更新", "update")} × {number(steps)} {t("次更新", "updates")}</p><p>{t("每参数约", "About")} {tokensPerParameter.toFixed(2)} {t("个训练 token", "training tokens per parameter")}</p></div></div>
		<p class="budget-formula">{t("状态内存", "State memory")} = {size} × 10⁶ × (4 + 4 + 4 + 4) bytes ÷ 2³⁰<br />tokens = {context} × {microbatch} × {accumulation} × {number(steps)}</p><p class="fine-print">{t("按所选近似参数档估算；真实参数量以项目配置为准。假定权重、梯度和 Adam 的一阶/二阶状态均为 FP32，合计 16 bytes/parameter。这个下界不包含激活、临时张量、数据缓存、框架、系统或 DPO 参考模型；它不能判断某个配置一定能跑。上下文与微批量增大还会增加激活内存。Token 预算假定序列填满且无 padding，是处理次数，可能包含重复语料。", "Uses rounded parameter tiers; actual counts come from project configurations. Assumes FP32 weights, gradients, and Adam first/second moments: 16 bytes per parameter. This lower bound excludes activations, temporary tensors, data buffers, framework, OS, and the DPO reference model; it does not guarantee a configuration will fit. Longer contexts and larger microbatches also increase activation memory. Token totals assume full sequences without padding and count processing, which may include repeated data.")}</p>
		<div class="scale-note"><strong>{size === 0.15 ? t("tiny：先跑少量更新，检查整条链路。", "tiny: run a few updates to check the chain.") : size === 30 ? t("30M：先把链路接通。", "30M: connect the full workflow.") : size === 100 ? t("100M：拿到首轮记录后再扩大。", "100M: scale after the first recorded run.") : t("500M：保留为测量后的选项。", "500M: keep this conditional on measurements.")}</strong><p>{size === 0.15 ? t("约 0.15M 仅用于此预算器的近似估算。实际参数量以项目配置为准，首跑关注有限损失、梯度、保存恢复和导出加载，不评判语言能力。", "Approximately 0.15M is a rounded calculator estimate. Use the project configuration for actual parameter counts. First verify finite loss, gradients, resuming, and export loading; this is not a language-capability benchmark.") : size === 30 ? t("用小预算确认数据、梯度、保存恢复、后训练与评测，再基于实际吞吐安排完整训练。", "Use a small budget to connect data, gradients, saving/resuming, post-training, and evaluation. Plan longer training from measured throughput.") : size === 100 ? t("先记录 30M 的峰值内存和 tokens/s，固定评测后再比较更大模型。", "Record the 30M run's peak memory and tokens/s, then compare a larger model using fixed evaluations.") : t("0.5B 从随机权重训练的计算量与内存需求，需要单独测量。0.5B 现成基座的 LoRA 微调是另一条支线。", "Training 0.5B from random weights requires separate compute and memory measurements. LoRA on an existing 0.5B base model is a separate track.")}</p></div>
		<div class="measurement-note"><strong>{t("在这台 Mac 上，下一步是测量。", "On this Mac, measurement comes next.")}</strong><p>{t("已核对 Apple M4 Air、8 核 GPU 与 16 GiB 统一内存；本轮磁盘可用空间约 12 GiB，会随时间变化。长跑前重新检查余量，并实测同配置的峰值内存、持续吞吐、温度影响和 checkpoint 大小。", "Hardware checked: MacBook Air M4, 8-core GPU, 16 GiB unified memory. Free disk was approximately 12 GiB during this session and changes over time. Recheck it before long runs; profile peak memory, sustained throughput, thermal effects, and checkpoint size for the same configuration.")}</p><label class="throughput-input">{t("你实测的持续吞吐（tokens/s，可留空）", "Your measured sustained throughput (tokens/s, optional)")}<input type="number" min="1" max="100000000" step="any" placeholder={t("尚无测量", "No measurement yet")} bind:value={throughput} /></label><p class="calculation" role="status">{runHours === null ? t("训练时长：等待实测输入。", "Run duration: awaiting a measured input.") : `${t("按输入吞吐推算", "Projection from entered throughput")}: ${runHours.toLocaleString(english ? "en-US" : "zh-CN", {maximumFractionDigits: 2})} h`}</p><p>{t("时长 = token 预算 ÷ tokens/s ÷ 3600。未包含评测、保存、加载与停顿；该输入仅用于临时试算，不写入分享链接，也不是本站测得的速度。", "Duration = token budget ÷ tokens/s ÷ 3600. Excludes evaluation, saving, loading, and pauses. Your input is a temporary estimate, is omitted from the share link, and is not a speed measured by this site.")}</p></div>
		<div class="share-row"><button class="plain" onclick={share}>{t("复制这份规划", "Copy this plan")} ↗</button><span role="status">{copyStatus === "ok" ? t("已复制配置链接。", "Configuration link copied.") : copyStatus === "error" ? t("请从地址栏复制已更新的配置链接。", "Copy the updated configuration link from the address bar.") : t("链接保留阶段和预算参数。", "The link preserves the stage and budget settings.")}</span></div>
	</section>
</section>

<style>
	.pipeline{border:1px solid var(--brand-line);border-radius:22px;overflow:hidden;background:var(--brand-surface);color:var(--brand-ink)}.workbench-heading{display:flex;justify-content:space-between;gap:16px;padding:20px 28px;font:9px/1.7 "JetBrains Mono",monospace;letter-spacing:.12em;border-bottom:1px solid var(--brand-line);color:var(--brand-muted)}.planning-dot{display:flex;align-items:center;gap:8px;color:var(--brand-accent)}.planning-dot:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--brand-accent)}.stage-nav{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));padding:22px 25px;gap:7px;border-bottom:1px solid var(--brand-line)}button{border:1px solid var(--brand-line);border-radius:25px;padding:11px 18px;background:var(--brand-peach);color:var(--brand-ink);font-family:inherit;font-size:12px;line-height:1.6;cursor:pointer;transition:background .2s,transform .2s}button:hover:not(:disabled){background:var(--brand-peach-hover);transform:translateY(-2px)}button:disabled{opacity:.4;cursor:default}.stage-nav button{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:10px;text-align:left;min-width:0;border-radius:9px;padding:14px 10px;background:transparent;border-color:transparent;line-height:1.4}.stage-nav button>span{font:9px monospace;color:var(--brand-muted)}.stage-nav button strong{font-size:11px;font-weight:500}.stage-nav button i{position:absolute;right:7px;top:13px;font-style:normal;opacity:.5;font-size:11px}.stage-nav button.active{background:var(--brand-accent);color:var(--brand-paper)}.stage-nav button.active>span{color:var(--brand-surface)}.stage-panel{display:grid;grid-template-columns:1.2fr .8fr;gap:50px;padding:40px 36px 30px}.step-code{font:9px/1.8 "JetBrains Mono",monospace;letter-spacing:.08em;color:var(--brand-clay)}.stage-copy h2{font:400 clamp(25px,3vw,37px)/1.45 Georgia,"Songti SC",serif;margin:17px 0 18px;letter-spacing:-.03em}.stage-copy p,.stage-insight p{font-size:13px;line-height:1